        vals = set(input_grid[r][c] for r in range(h))
        if len(vals) == 1:
            vert_divs.append(c)

    non_div_rows = sorted(set(range(h)) - set(horiz_divs))
    bands = []
    current_band = []
    prev_r = -1

    for r in non_div_rows:
        if prev_r != r - 1:
            if current_band:
                bands.append(current_band)
                current_band = []
        current_band.append(r)
        prev_r = r
    if current_band:
        bands.append(current_band)

