def solve_v14(input_grid):
    """Version that uses ALL horizontal dividers as boundaries."""
    h, w = len(input_grid), len(input_grid[0])

    horiz_divs = []
    for r in range(h):
        if len(set(input_grid[r])) == 1:
            horiz_divs.append(r)

    vert_divs = []
    for c in range(w):
        vals = set(input_grid[r][c] for r in range(h))
        if len(vals) == 1:
            vert_divs.append(c)

    print(f"horiz_divs: {horiz_divs}")
    print(f"vert_divs: {vert_divs}\n")

    # Use ALL unique divider rows as boundaries
    unique_div_rows = list(set(horiz_divs))

    # Build bands between consecutive dividers
    bands = []
    prev_r = -1

    for rd in sorted(unique_div_rows):
        if prev_r + 1 < rd:
            band_rows = [r for r in range(prev_r + 1, rd) if r not in set(horiz_divs)]
            if band_rows:
                bands.append(band_rows)
        prev_r = rd

    # After last divider
    if prev_r + 1 < h:
        band_rows = [r for r in range(prev_r + 1, h) if r not in set(horiz_divs)]
        if band_rows:
            bands.append(band_rows)

    def count_adjacent_pair_types(grid_rows, start_col, end_col, include_vertical=True):
        """Count distinct adjacent pair values (horizontal and/or vertical)."""
        pair_types = set()
        for r in grid_rows:
            # Horizontal pairs
            for c in range(start_col, min(end_col, w) - 1):
                val = input_grid[r][c]
                if val == input_grid[r][c+1]:
                    pair_types.add(val)
            # Vertical pairs
            if include_vertical and len(grid_rows) >= 2:
                for r_idx in range(1, len(grid_rows)):
                    for c in range(start_col, min(end_col, w)):
                        val = input_grid[grid_rows[r_idx]][c]
                        if val == input_grid[grid_rows[r_idx-1]][c]:
                            pair_types.add(val)
        return len(pair_types), pair_types

    section_starts = [0] + [v + 1 for v in vert_divs[:-1]]
    if vert_divs:
        section_starts.append(vert_divs[-1] + 1)

    # Get max num_types across all sections in ALL bands
    max_types = 0
    for band_rows in bands:
        for i in range(len(section_starts)):
            vs = section_starts[i]
            es = section_starts[i+1] if i < len(section_starts) - 1 else w
            num_types, _ = count_adjacent_pair_types(band_rows, vs, es)
            max_types = max(max_types, num_types)

    print(f"max_types: {max_types}, num_bands: {len(bands)}\n")

    result = []

    for band_idx, band_rows in enumerate(bands):
        result.append([])

        for i in range(len(section_starts)):
            vs = section_starts[i]
            es = section_starts[i+1] if i < len(section_starts) - 1 else w

            num_types, types = count_adjacent_pair_types(band_rows, vs, es)

            if num_types == max_types:
                result[-1].append(1)
            else:
                result[-1].append(5)

    return result

